import { useNavigate } from "react-router-dom";
import { useState } from "react";
import { NqfDropdown } from "../components/nqfSelect.jsx";
import { signUpWithGoogle } from "../services/authService";

const PROVINCES = [
  "Eastern Cape", "Free State", "Gauteng", "KwaZulu-Natal",
  "Limpopo", "Mpumalanga", "Northern Cape", "North West", "Western Cape",
];

export default function SignupApplicant() {
  const navigate = useNavigate();
  const [form, setForm] = useState({
    firstName: "", lastName: "", province: "", qualification: ""
  });
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");

  const set = (field) => (e) =>
    setForm(prev => ({ ...prev, [field]: e.target.value }));

  const validateForm = () => {
    if (!form.firstName.trim()) return "First name is required";
    if (!form.lastName.trim()) return "Last name is required";
    if (!form.province) return "Province is required";
    if (!form.qualification) return "Qualification is required";
    return null;
  };

  const handleGoogleSignup = async () => {
    setErrorMsg("");
    if (loading) return;

    const validationError = validateForm();
    if (validationError) {
      setErrorMsg(validationError);
      return;
    }

    setLoading(true);

    try {
      const { user, existingUser, role } = await signUpWithGoogle("applicant", {
        firstName: form.firstName,
        lastName: form.lastName,
        province: form.province,
        qualification: form.qualification,
      });

      if (existingUser) {
        setErrorMsg("You already have an account. Please log in.");
        setLoading(false);
        return;
      }

      if (role && role !== "applicant") {
        setErrorMsg(
          "You already have an account with a different role. Please log in."
        );
        setLoading(false);
        return;
      }

      console.log("Applicant created:", user?.uid);
      navigate("/applicant-dashboard");

    } catch (error) {
      console.error("Signup error:", error);
      setErrorMsg(error?.message || "Signup failed. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <form noValidate>
      <fieldset>
        <legend>Personal details</legend>
        {errorMsg && <p style={{ color: "red" }}>{errorMsg}</p>}
        <label>First name<input value={form.firstName} onChange={set("firstName")} /></label>
        <label>Last name<input value={form.lastName} onChange={set("lastName")} /></label>
        <label>Province
          <select value={form.province} onChange={set("province")}>
            <option value="">Select province</option>
            {PROVINCES.map(p => <option key={p} value={p}>{p}</option>)}
          </select>
        </label>
        <label>Qualification
          <NqfDropdown value={form.qualification} onChange={set("qualification")} />
        </label>
      </fieldset>
      <button type="button" onClick={handleGoogleSignup} disabled={loading}>
        {loading ? "Signing in..." : "Continue with Google"}
      </button>
    </form>
  );
}