// pages/LoginPage.jsx
import { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./loginPage.css";
import { signUpWithGoogle } from "../services/authService";

export default function LoginPage() {
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleGoogleLogin = async () => {
    setLoading(true);
    try {
      const { role } = await signUpWithGoogle(); // role fetched from Firestore

      const userRole = role?.trim().toLowerCase();
      console.log("Google login successful, role:", userRole);

      if (!userRole) {
        alert("No account found. Please sign up first.");
        return;
      }

      if (userRole === "admin") navigate("/dashboard/admin");
      else if (userRole === "provider") navigate("/dashboard/provider");
      else if (userRole === "applicant") navigate("/dashboard/applicant");
      else alert("Unknown role. Contact support.");

    } catch (error) {
      console.error("GOOGLE LOGIN ERROR:", error);
      alert(error.message || "Google login failed. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <main className="login-page">
      <aside className="login-left">
        <header className="brand">
          <span className="brand-mark">UBUNTU</span>
          <span className="brand-name">CAREERS</span>
        </header>
        <section className="hero">
          <h1>Connect.<br />Learn.<br />Grow.</h1>
          <p>South Africa's platform linking work-seekers with SETA-accredited learnerships, apprenticeships and internships.</p>
        </section>
      </aside>

      <section className="login-right">
        <h4>Sign in to your account</h4>
        <button onClick={handleGoogleLogin} className="btn" disabled={loading}>
          {loading ? "Signing in..." : "Sign in with Google"}
        </button>
      </section>
    </main>
  );
}